effect.shader:
#define PI 3.14159265359
mat2 rot2m(float a) {
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
void main () {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseAlpha = texColor.a;
vec2 st = ((vec2(uv.x, 1.0 - uv.y) * acScreenSize) - acLayerCenter) / acLayerSize;
st.y *= acLayerSize.y / max(acLayerSize.x, 1.0);
st /= max(scale, 0.001);
st *= rot2m(angle * 0.0174532925);
st += vec2(position.x, position.y) * vec2(-1.0, 1.0) / 500.0;
float t = progress;
if (autoProgress) {
t += acTime * speed;
}
float ax = abs(st.x);
float ay = abs(st.y);
float radius = max(ax, ay);
radius = max(radius, 0.0001);
float u = 1.0 / radius + t;
float v = atan(st.y, st.x) / PI + twist * radius;
vec2 tunUv = vec2(u, v) * gridAmount;
vec2 grid = abs(fract(tunUv) - 0.5) * 2.0;
float lineX = smoothstep(thickness1, thickness1 + 0.05, grid.x);
float lineY = smoothstep(thickness2, thickness2 + 0.05, grid.y);
float depthFade = clamp(radius * 2.0, 0.0, 1.0);
float gridPattern = 1.0 - (lineX * lineY);
gridPattern *= depthFade;
vec4 patternColor = mix(colorBG, colorFG, gridPattern);
vec4 factor = patternColor;
vec4 resultfinal;
vec3 tcSafe = texColor.rgb / max(texColor.a, 0.001);
if (blendMode == 0) {
resultfinal = factor * brightness;
} else if (blendMode == 1) {
factor *= brightness;
vec3 mixed = factor.rgb + vec3(1.0) * (1.0 - factor.a);
resultfinal = vec4(tcSafe * mixed, 1.0);
} else if (blendMode == 2) {
factor *= brightness;
resultfinal = vec4(1.0 - ((1.0 - tcSafe) * (1.0 - factor.rgb)), 1.0);
}
resultfinal = clamp(resultfinal, 0.0, 1.0);
resultfinal.rgb *= baseAlpha;
resultfinal.a = baseAlpha;
vec4 outputColor = mix(texColor, resultfinal, alpha * factor.a);
gl_FragColor = outputColor;
}
